    public FType getRange() {
        return target.getRange();
    }

    @Override
    public IdOrOpOrAnonymousName getFnName() {
        return target.getFnName();
    }

    @Override
    public FType type() {
        return target.type();
    }

    @Override
    public boolean seqv(FValue other) {
        return this == other;
    }

    @Override
    public String toString() {
        return "coerced " + target;
    }
}

