private SingleFcn numeralTieDefault(List<FValue> args, List<Overload> someOverloads) {
    if (System.getProperty("probe.q.tie", "on").equals("off")) return null;
    List<FValue> read = new ArrayList<FValue>(args);
    boolean any = false;
    for (int j = 0; j < args.size(); j++) {
        FValue a = args.get(j);
        if (!(a instanceof FIntLiteral)) continue;
        String n = com.sun.fortress.interpreter.evaluator.EvaluatorBase.numeralDefault(Collections.singletonList(a));
        FType target = null;
        for (FType t : Coercions.coercionTargets(a, getWithin())) {
            if (n.equals(t.getName())) target = t;
        }
        if (target == null) return null;
        FValue c;
        try {
            c = Coercions.coerce(target, a);
        }
        catch (FortressException ex) {
            return null;
        }
        if (c == null) return null;
        read.set(j, c);
        any = true;
    }
    if (!any) return null;
    SingleFcn chosen = bestMatchInternal(read, someOverloads, true);
    if (chosen == null) return null;
    return new NumeralDefaultCall(chosen, this);
}

